+      :additions="changeFile.additions"
+      :deletions="changeFile.deletions"
+      :remainder="changeFile.additions + changeFile.deletions"
+      detail
+    />
+    <div class="detail-file-meta" :class="{ warning: isDeleted && importerCount > 0 }">
+      {{ metaText }}
+    </div>
+  </button>
